mapper.select:
SELECT 'OPP:'||opp_id FROM tb_sl_opp WHERE opp_stat_cd='ING'
UNION SELECT 'ASGN:'||asgn_id FROM tb_pj_asgn WHERE dev_id=#{developerId}
UNION SELECT 'PROJECT:'||proj_id FROM tb_pj_asgn WHERE dev_id=#{developerId}
UNION SELECT 'PAY:'||pay_ym FROM tb_hr_mon_pay WHERE dev_id=#{developerId}
UNION SELECT 'OPP:'||opp_id FROM tb_sl_tent_asgn WHERE dev_id=#{developerId} AND tent_stat_cd='ACT'
ORDER BY 1
